MAIN='\n#include "lua_object_handles.hpp"\n#include "interfaces/lua/api400_fields.guards.hpp"\n#include "interfaces/lua/bitset128_api.hpp"\n#include "interfaces/lua/engine_color_mod.hpp"\n#include "infrastructure/call/engine_call_access.hpp"\n#if __has_include("interfaces/lua/api600_game.hpp")\n#include "interfaces/lua/api600_game.hpp"\n#endif\n#include <cassert>\n#include <cstdio>\n#include <cstring>\nusing namespace isaac::runtime;using Vec=LuaRuntime::VectorHandle;\nvoid* Api500WorldRoom(){return g_RoomBytes.data();}void* Api500WorldPool(){return nullptr;}\nunsigned damageCalls{},explosionCalls{},flagCalls{},attractorCalls{},gameRenderCalls{},roomRenderCalls{},colorCalls{},angleCalls{};\nvoid Damage(void*self,const Vec&pos,float damage,float radius,bool line,void*source,BitSet128Value flags,std::uint64_t df,bool ds){assert(self==g_GameBytes.data()&&pos.x==3&&pos.y==4&&damage==12.5F&&radius==30);if(damageCalls==0)assert(line&&!source&&!flags.low&&!flags.high&&df==4&&!ds);else assert(!line&&source==g_Entities[kPlayer].data()&&flags.low==1&&flags.high==0x8000000000000000ULL&&df==0x8000000000000004ULL&&ds);++damageCalls;}\nvoid Explode(void*self,const Vec&pos,float damage,BitSet128Value flags,const EngineColorMod&color,void*source,float radius,bool line,std::uint64_t df,bool ds){assert(self==g_GameBytes.data()&&pos.x==3&&damage==12.5F);if(explosionCalls==0)assert(!flags.low&&!flags.high&&color.tint[0]==1&&!source&&radius==1&&line&&df==4&&!ds);else assert(flags.high==0x8000000000000000ULL&&color.tint[0]==.25F&&source==g_Entities[kPlayer].data()&&radius==2&&!line&&df==8&&ds);++explosionCalls;}\nvoid Flags(void*self,const Vec&pos,float radius,BitSet128Value flags,void*source,float mult){assert(self==g_GameBytes.data()&&pos.y==4&&radius==30&&flags.low==1&&flags.high==0x8000000000000000ULL);if(flagCalls==0)assert(!source&&mult==1);else assert(source==g_Entities[kPlayer].data()&&mult==2);++flagCalls;}\nvoid Attractor(void*self,const Vec&pos,float force,float radius,void*predicate){assert(self==g_GameBytes.data()&&pos.x==3&&!predicate);if(attractorCalls==0)assert(force==10&&radius==250);else assert(force==2&&radius==3);++attractorCalls;}\nvoid GameRender(void*self){assert(self==g_GameBytes.data());++gameRenderCalls;}void RoomRender(void*self){assert(self==g_RoomBytes.data());++roomRenderCalls;}\nvoid ColorSet(void*self,const EngineColorMod*c,std::int32_t duration,std::int32_t priority,bool fade,bool share){assert(self==g_Entities[kEnemyA].data()&&duration==-1&&priority==255&&!fade&&share&&c->tint[0]==.25F);std::memcpy(static_cast<unsigned char*>(self)+0x220,c,sizeof(*c));++colorCalls;}\ntemplate<class T>T At(const void*p,unsigned o){T v{};std::memcpy(&v,static_cast<const unsigned char*>(p)+o,sizeof(v));return v;}\nvoid AngleSet(void*self,float angle){assert(self==g_Entities[kSizeOnly].data()&&angle==25);const auto old=At<float>(self,0x40c);std::memcpy(static_cast<unsigned char*>(self)+0x410,&old,4);std::memcpy(static_cast<unsigned char*>(self)+0x408,&angle,4);std::memcpy(static_cast<unsigned char*>(self)+0x40c,&angle,4);const float rot=angle-90;std::memcpy(static_cast<unsigned char*>(self)+0x134,&rot,4);++angleCalls;}\nint main(){static_cast<void>(kScriptTemplate);static_cast<void>(&HarnessHasCollectible);static_cast<void>(&BuildPrelude);static_cast<void>(&ExpectNumber);CreateBlocks();FillEntities();for(auto&v:g_Entities)v.resize(0x4000);WriteWord(g_Entities[kEnemyA],0,g_EngineBase+kEntityNpcVtableOffset);WriteWord(g_Entities[kSizeOnly],0,g_EngineBase+kEntityLaserVtableOffset);WriteAt<std::uint32_t>(g_Entities[kSizeOnly],kEntityTypeOffset,7);PublishLists();PublishGame();PublishEntityList(g_RoomBytes,true);LuaRuntime::SetEngineModuleBase(g_EngineBase);LuaRuntime::SetGameBindings(g_EngineBase+kGameOwnerGlobalSlotOffset,0x2222);\nconst unsigned char g3493396[]={233,35,14,109,253,123,15,169,253,195,3,145,252,111,16,169};std::memcpy(g_ModuleBytes.data()+3493396,g3493396,16);\nconst unsigned char g3497080[]={253,123,11,169,253,195,2,145,252,111,12,169,250,103,13,169};std::memcpy(g_ModuleBytes.data()+3497080,g3497080,16);\nconst unsigned char g3499836[]={233,35,16,109,253,123,17,169,253,67,4,145,252,111,18,169};std::memcpy(g_ModuleBytes.data()+3499836,g3499836,16);\nconst unsigned char g3522436[]={253,123,6,169,253,131,1,145,252,111,7,169,250,103,8,169};std::memcpy(g_ModuleBytes.data()+3522436,g3522436,16);\nconst unsigned char g3482412[]={252,111,15,169,250,103,16,169,248,95,17,169,246,87,18,169};std::memcpy(g_ModuleBytes.data()+3482412,g3482412,16);\nconst unsigned char g4717336[]={253,123,4,169,253,3,1,145,252,111,5,169,250,103,6,169};std::memcpy(g_ModuleBytes.data()+4717336,g4717336,16);\nconst unsigned char g1007416[]={1,1,39,30,0,8,4,189,0,40,33,30,0,52,1,189};std::memcpy(g_ModuleBytes.data()+1007416,g1007416,16);\nconst unsigned char g408468[]={246,87,6,169,244,79,7,169,245,3,5,42,247,3,4,42};std::memcpy(g_ModuleBytes.data()+408468,g408468,16);\nconst unsigned char g378708[]={8,16,65,249,9,20,65,249,10,24,65,249,8,164,19,169};std::memcpy(g_ModuleBytes.data()+378708,g378708,16);\nconst unsigned char g1013428[]={104,54,17,145,233,31,128,82,116,10,5,185,96,98,17,145};std::memcpy(g_ModuleBytes.data()+1013428,g1013428,16);\nconst unsigned char g402708[]={8,4,71,57,243,3,0,170,136,3,0,52,104,26,71,57};std::memcpy(g_ModuleBytes.data()+402708,g402708,16);\n\nstd::memcpy(g_ModuleBytes.data()+api400_fields::kLaserEntry,api400_fields::kLaserGuard.data(),16);\n#if __has_include("interfaces/lua/api600_game.hpp")\nSetApi600GameNativeTestBindings({{engine_call::AddressOfFunction(&Damage),engine_call::AddressOfFunction(&Explode),engine_call::AddressOfFunction(&Flags),engine_call::AddressOfFunction(&Attractor),engine_call::AddressOfFunction(&GameRender),engine_call::AddressOfFunction(&RoomRender),engine_call::AddressOfFunction(&AngleSet),engine_call::AddressOfFunction(&ColorSet)}});\n#endif\nEngineColorMod c{};c.tint[0]=.75F;std::memcpy(g_Entities[kEnemyA].data()+0x220,&c,sizeof(c));WriteAt<float>(g_Entities[kSizeOnly],0x40c,5);\nconst char*script=R"lua(\nlocal game=Game();local pos=Vector(3,4);local source=Isaac.FindByType(1)[1]:ToPlayer();local f=BitSet128(1,0x8000000000000000)\nassert(select(\'#\',game:BombDamage(pos,12.5,30))==0);game:BombDamage(pos,12.5,30,false,source,f,0x8000000000000004,true)\ngame:BombExplosionEffects(pos,12.5);game:BombExplosionEffects(pos,12.5,f,Color(.25,.5,.75,1),source,2,false,true,8)\ngame:BombTearflagEffects(pos,30,f);game:BombTearflagEffects(pos,30,f,source,2)\ngame:UpdateStrangeAttractor(pos);game:UpdateStrangeAttractor(pos,2,3)\ngame:Render();game:GetRoom():Render()\nlocal e=Isaac.FindByType(20)[1];assert(e.Color.R==.75);local c=e.Color;c.R=.1;assert(e.Color.R==.75);e.Color=Color(.25,.5,.75,1);assert(e.Color.R==.25)\nlocal l=Isaac.FindByType(7)[1]:ToLaser();assert(l.Angle==5);l.Angle=25;assert(l.Angle==25 and l.LastAngleDegrees==5 and l.StartAngleDegrees==25 and l.SpriteRotation==-65);assert(l.SampleLaser==false);l.SampleLaser=0;assert(l.SampleLaser==true)\nassert(not pcall(function()game:BombDamage({},1,2)end));assert(not pcall(function()game:BombExplosionEffects(pos,1,{},nil)end));assert(not pcall(function()e.Color={}end));assert(not pcall(function()l.Angle={}end))\n)lua";\nif(LuaRuntime::InitializeFromBuffer(script,std::strlen(script),"@api600-native.lua")!=LuaRuntime::LuaInitResult::Success){LuaRuntime::LuaErrorHistoryEntryView e[8]{};auto n=LuaRuntime::CopyLuaErrorHistory(e,8);for(std::size_t i=0;i<n;++i)std::fprintf(stderr,"%s\\n",e[i].text);return 1;}assert(damageCalls==2&&explosionCalls==2&&flagCalls==2&&attractorCalls==2&&gameRenderCalls==1&&roomRenderCalls==1&&colorCalls==1&&angleCalls==1);return 0;}\n'
